// WiFi verilerini ayrıştıran yardımcı metodimport 'package:easy_localization/easy_localization.dart';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:wifi_iot/wifi_iot.dart';Map<String, String> parseWifiData(String wifiString) {  final Map<String, String> result = {};  // WIFI:S:<SSID>;T:<WPA|WEP|>;P:<password>;H:<hidden>;  final pattern = RegExp(r'([STPH]):([^;]*);');  final matches = pattern.allMatches(wifiString);  for (var match in matches) {    if (match.groupCount >= 2) {      final key = match.group(1);      final value = match.group(2);      if (key != null && value != null) {        result[key] = value;      }    }  }  return result;}// WiFi ağına bağlanma işlemivoid connectToWifi(Map<String, String> wifiData) {  final ssid = wifiData['S'] ?? '';  final password = wifiData['P'] ?? '';  final securityType = wifiData['T'] ?? '';  print('Connecting to WiFi: SSID=$ssid, Password=$password, Security=$securityType');  WiFiForIoTPlugin.connect(ssid,    password: password.isNotEmpty ? password : null,    joinOnce: true,    security:    securityType == 'WPA'        ? NetworkSecurity.WPA        : securityType == 'WEP'        ? NetworkSecurity.WEP        : NetworkSecurity.NONE,);}// WiFi bağlantı bilgilerini paylaşmavoid shareWifiDetails(BuildContext context,Map<String, String> wifiData) {  final ssid = wifiData['S'] ?? '';  final password = wifiData['P'] ?? '';  final securityType = wifiData['T'] ?? '';  final shareText = 'WiFi Ağı: $ssid\nParola: $password\nGüvenlik: $securityType';  // Paylaşım işlemi için platform-spesifik kod gerekebilir  // Şimdilik sadece kopyalama işlemi yapalım  Clipboard.setData(ClipboardData(text: shareText)).then((_) {    ScaffoldMessenger.of(context).showSnackBar(      SnackBar(content: Text('nfc.scan.wifi_copied'.tr())),    );  });}// vCard verilerini ayrıştıran yardımcı metodMap<String, String> parseVCardData(String vCardString) {  final Map<String, String> result = {};  // vCard formatındaki verileri satır satır ayrıştır  final lines = vCardString.split('\n');  for (var line in lines) {    // Boş satırları atla    if (line.trim().isEmpty) continue;    // Önemli alanları kontrol et (FN, TEL, EMAIL, ADR)    if (line.startsWith('FN:')) {      result['FN'] = line.substring(3).trim();    } else if (line.startsWith('TEL')) {      // Telefon numarasını ayıkla      final colonIndex = line.indexOf(':');      if (colonIndex != -1) {        result['TEL'] = line.substring(colonIndex + 1).trim();      }    } else if (line.startsWith('EMAIL')) {      // E-posta adresini ayıkla      final colonIndex = line.indexOf(':');      if (colonIndex != -1) {        result['EMAIL'] = line.substring(colonIndex + 1).trim();      }    } else if (line.startsWith('ADR')) {      // Adresi ayıkla      final colonIndex = line.indexOf(':');      if (colonIndex != -1) {        result['ADR'] = line.substring(colonIndex + 1).trim();      }    }  }  return result;}